package com.foodflow.orders.client;import com.foodflow.orders.dto.CatalogItemResponse;import com.foodflow.orders.dto.StockRequest;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@FeignClient(name="catalog-service",url="${foodflow.catalog.url:}",configuration=com.foodflow.orders.config.FeignConfig.class) public interface CatalogClient {@GetMapping("/api/catalog/menu/{id}") CatalogItemResponse get(@PathVariable UUID id);@GetMapping("/api/catalog/restaurants/mine") java.util.Map<String,Object> ownerRestaurant();@PostMapping("/api/catalog/internal/inventory/{id}/reserve") CatalogItemResponse reserve(@PathVariable UUID id,@RequestBody StockRequest r);@PostMapping("/api/catalog/internal/inventory/{id}/release") void release(@PathVariable UUID id,@RequestBody StockRequest r);}
